import{_ as o,a}from"./chunks/devtools-tabs.ByMI8UZy.js";import{_ as n,o as i,c as r,j as e,a as l,aj as s}from"./chunks/framework.C6uXqnaX.js";const v=JSON.parse('{"title":"DevTools Overview","description":"","frontmatter":{},"headers":[],"relativePath":"en/tools/devtools.md","filePath":"en/tools/devtools.md"}'),d={name:"en/tools/devtools.md"};function p(c,t,u,h,f,b){return i(),r("div",null,t[0]||(t[0]=[e("h1",{id:"devtools-overview",tabindex:"-1"},[l("DevTools Overview "),e("a",{class:"header-anchor",href:"#devtools-overview","aria-label":'Permalink to "DevTools Overview"'},"​")],-1),e("p",null,"Angular DevTools is a browser extension that provides debugging and profiling capabilities for Angular applications.",-1),e("iframe",{src:"https://www.youtube.com/embed/bavWOHZM6zE",title:"Video",style:{width:"100%","aspect-ratio":"16/9",border:"0"},allowfullscreen:""},null,-1),s('<p>Install Angular DevTools from the <a href="https://chrome.google.com/webstore/detail/angular-developer-tools/ienfalfjdbdpebioblfackkekamfmbnh" target="_blank" rel="noreferrer">Chrome Web Store</a> or from <a href="https://addons.mozilla.org/firefox/addon/angular-devtools/" target="_blank" rel="noreferrer">Firefox Addons</a>.</p><p>You can open Chrome or Firefox DevTools on any web page by pressing <kbd>F12</kbd> or <kbd><kbd>Ctrl</kbd>+<kbd>Shift</kbd>+<kbd>I</kbd></kbd> (Windows or Linux) and <kbd><kbd>Fn</kbd>+<kbd>F12</kbd></kbd> or <kbd><kbd>Cmd</kbd>+<kbd>Option</kbd>+<kbd>I</kbd></kbd> (Mac). Once browser DevTools is open and Angular DevTools is installed, you can find it under the &quot;Angular&quot; tab.</p><div class="tip custom-block"><p class="custom-block-title">HELPFUL</p><p>Chrome&#39;s new tab page does not run installed extensions, so the Angular tab will not appear in DevTools. Visit any other page to see it.</p></div><img src="'+o+'" alt="An overview of Angular DevTools showing a tree of components for an application."><h2 id="open-your-application" tabindex="-1">Open your application <a class="header-anchor" href="#open-your-application" aria-label="Permalink to &quot;Open your application&quot;">​</a></h2><p>When you open the extension, you&#39;ll see four additional tabs:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Tabs</th><th style="text-align:left;">Details</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="/en/tools/devtools/component">Components</a></td><td style="text-align:left;">Lets you explore the components and directives in your application and preview or edit their state.</td></tr><tr><td style="text-align:left;"><a href="/en/tools/devtools/profiler">Profiler</a></td><td style="text-align:left;">Lets you profile your application and understand what the performance bottleneck is during change detection execution.</td></tr><tr><td style="text-align:left;"><a href="/en/tools/devtools/injectors">Injector Tree</a></td><td style="text-align:left;">Lets you visualize the Environment and Element Injector hierarchy</td></tr><tr><td style="text-align:left;"><a href="/en/tools/devtools/router">Router Tree</a></td><td style="text-align:left;">Lets you visualize the routing tree of your application.</td></tr></tbody></table><p>A <code>Transfer State</code> tab also appears when the application uses hydration.</p><div class="tip custom-block"><p class="custom-block-title">HELPFUL</p><p>For users of Chromium based browsers, you might be interested in the <a href="/en/best-practices/profiling-with-chrome-devtools">Performance panel integration</a>.</p></div><img src="'+a+'" alt="A screenshot of the top of Angular DevTools illustrating two tabs in the upper-left corner, one labeled &#39;Components&#39; and another labeled &#39;Profiler&#39;."><p>In the top-right corner of Angular DevTools you&#39;ll find the information button which open a popover. The information popover contains among others what version of Angular is running on the page as well as the devtools version.</p><h3 id="angular-application-not-detected" tabindex="-1">Angular application not detected <a class="header-anchor" href="#angular-application-not-detected" aria-label="Permalink to &quot;Angular application not detected&quot;">​</a></h3><p>If you see an error message &quot;Angular application not detected&quot; when opening Angular DevTools, this means it is not able to communicate with an Angular app on the page. The most common reason for this is because the web page you are inspecting does not contain an Angular application. Double check that you are inspecting the right web page and that the Angular app is running.</p><h3 id="we-detected-an-application-built-with-production-configuration" tabindex="-1">We detected an application built with production configuration <a class="header-anchor" href="#we-detected-an-application-built-with-production-configuration" aria-label="Permalink to &quot;We detected an application built with production configuration&quot;">​</a></h3><p>If you see an error message &quot;We detected an application built with production configuration. Angular DevTools only supports development builds.&quot;, this means that an Angular application was found on the page, but it was compiled with production optimizations. When compiling for production, Angular CLI removes various debug features to minimize the amount of the JavaScript on the page to improve performance. This includes features needed to communicate with DevTools.</p><p>To run DevTools, you need to compile your application with optimizations disabled. <code>ng serve</code> does this by default. If you need to debug a deployed application, disable optimizations in your build with the <a href="/en/reference/configs/workspace-config#optimization-configuration"><code>optimization</code> configuration option</a> (<code>{&quot;optimization&quot;: false}</code>).</p>',16)]))}const w=n(d,[["render",p]]);export{v as __pageData,w as default};
